CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"firstName" TEXT,"language" TEXT NOT NULL DEFAULT 'es',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "User_email_key" ON "User"("email");CREATE TABLE "GlucoseReading" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"value" DOUBLE PRECISION NOT NULL,"unit" TEXT NOT NULL DEFAULT 'mg/dL',"source" TEXT NOT NULL DEFAULT 'manual',"recordedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GlucoseReading_pkey" PRIMARY KEY ("id"));CREATE TABLE "InsulinEntry" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"units" DOUBLE PRECISION NOT NULL,"insulinType" TEXT NOT NULL,"recordedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InsulinEntry_pkey" PRIMARY KEY ("id"));ALTER TABLE "GlucoseReading" ADD CONSTRAINT "GlucoseReading_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "InsulinEntry" ADD CONSTRAINT "InsulinEntry_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;CREATE INDEX "GlucoseReading_userId_recordedAt_idx" ON "GlucoseReading"("userId","recordedAt");CREATE INDEX "InsulinEntry_userId_recordedAt_idx" ON "InsulinEntry"("userId","recordedAt");